  'tpl.warnUnclosedTag': 'ਇਸ HTML ਵਿੱਚ ਕੁਝ ਟੈਗ ਠੀਕ ਤਰ੍ਹਾਂ ਬੰਦ ਨਹੀਂ ਲੱਗਦੇ — ਇਸ ਨਾਲ ਈਮੇਲ ਦੇ ਕੁਝ ਹਿੱਸਿਆਂ ਵਿੱਚ ਲੇਆਉਟ ਟੁੱਟ ਸਕਦਾ ਹੈ।',
  'tpl.warnMismatchedTag': 'ਕੁਝ ਬੰਦ ਕਰਨ ਵਾਲੇ ਟੈਗ ਆਪਣੇ ਖੋਲ੍ਹਣ ਵਾਲੇ ਟੈਗਾਂ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ — HTML ਢਾਂਚੇ ਨੂੰ ਦੁਬਾਰਾ ਜਾਂਚੋ।',
