  'dyn.howItWorks': 'ਡਾਇਨਾਮਿਕ ਫ਼ੀਲਡ ਤੁਹਾਨੂੰ ਤਕਨੀਕੀ ਲਿਖਤ ਯਾਦ ਰੱਖਣ ਦੀ ਬਜਾਏ "Customer Name" ਵਰਗਾ ਸੌਖਾ ਨਾਮ ਲਿਖਣ ਦਿੰਦੇ ਹਨ। ਕੈਂਪੇਨ ਭੇਜੇ ਜਾਣ ਸਮੇਂ, ਇਹ ਆਪਣੇ ਆਪ ਹਰ ਪ੍ਰਾਪਤਕਰਤਾ ਦੇ ਅਸਲ ਮੁੱਲ ਨਾਲ ਬਦਲ ਜਾਂਦਾ ਹੈ — ਉਦਾਹਰਨ ਲਈ, "Customer Name" ਨੇਹਾ ਲਈ "Neha Kulkarni" ਅਤੇ ਅਮਿਤ ਲਈ "Amit Shah" ਬਣ ਜਾਂਦਾ ਹੈ। ਤਕਨੀਕੀ ਵੇਰੀਏਬਲ ਇੱਥੇ ਸਿਰਫ਼ ਵਾਧੂ ਵੇਰਵੇ ਵਜੋਂ ਦਿਖਾਇਆ ਗਿਆ ਹੈ; ਤੁਹਾਨੂੰ ਇਸਨੂੰ ਕਦੇ ਵੀ ਖੁਦ ਟਾਈਪ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।',
