  'send.estimateAccountNote': 'ਇਹ ਇੱਕ ਮੋਟਾ ਅਨੁਮਾਨ ਹੈ (ਸਿਰਫ਼ ਬੈਚ ਆਕਾਰ × ਉਡੀਕ ਦਾ ਸਮਾਂ)। ਅਸਲੀ ਗਿਣਤੀ ਇਸ ਗੱਲ ਉੱਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ ਕਿ ਕਿਹੜਾ ਈਮੇਲ ਖਾਤਾ ਇਸਨੂੰ ਭੇਜਦਾ ਹੈ ਅਤੇ ਉਸ ਖਾਤੇ ਦੀ ਰੋਜ਼ਾਨਾ ਸੀਮਾ — ਸਹੀ ਅਨੁਮਾਨ ਲਈ ਕੈਂਪੇਨ ਵਿਜ਼ਾਰਡ ਵਿੱਚ ਇੱਕ ਅਸਲੀ ਦਰਸ਼ਕ ਵਰਗ ਚੁਣੋ।',
