  'send.subscribeDesc': 'ਕੁਝ ਈਮੇਲ ਉਹਨਾਂ ਲੋਕਾਂ ਨੂੰ ਜਾਂਦੇ ਹਨ ਜੋ ਹਾਲੇ ਤੁਹਾਡੀ ਸੂਚੀ ਉੱਤੇ ਨਹੀਂ ਹਨ। ਸਬਸਕ੍ਰਾਈਬ ਬਟਨ ਉਹਨਾਂ ਨੂੰ ਹੋਰ ਮੰਗਣ ਦਿੰਦਾ ਹੈ। ਜੋ ਵੀ ਇਸਨੂੰ ਦਬਾਉਂਦਾ ਹੈ ਉਹ ਤੁਹਾਡੇ ਸਬਸਕ੍ਰਾਈਬਰ ਪੰਨੇ ਉੱਤੇ ਆ ਜਾਂਦਾ ਹੈ, ਇਸ ਕੈਂਪੇਨ ਦੇ ਨਾਮ ਨਾਲ — ਤਾਂ ਜੋ ਤੁਹਾਨੂੰ ਹਮੇਸ਼ਾ ਪਤਾ ਰਹੇ ਉਹ ਕਿੱਥੋਂ ਆਏ।',
