  'acc.credRefreshedText': 'ਮਿਆਦ ਪੁੱਗੇ OAuth ਟੋਕਨ ਸਰਵਰ ਉੱਤੇ ਹੀ ਨਵੇਂ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਤੁਹਾਨੂੰ ਹਰ ਹਫ਼ਤੇ ਦੁਬਾਰਾ ਸਾਈਨ ਇਨ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।',
