  'set.quietDesc': 'ਕਤਾਰ ਵਿੱਚ ਲੱਗੇ ਈਮੇਲ ਪ੍ਰਾਪਤਕਰਤਾ ਦੇ ਸਮਾਂ ਖੇਤਰ ਵਿੱਚ ਸਵੇਰ ਤੱਕ ਉਡੀਕ ਕਰਦੇ ਹਨ।',
  'set.sendingNote': 'ਤੁਹਾਡੇ ਇੱਥੇ ਸੈੱਟ ਕੀਤੇ ਬੈਚ ਆਕਾਰ ਅਤੇ ਵਕਫ਼ਾ ਹਰ ਨਵੇਂ ਕੈਂਪੇਨ ਦਾ ਸ਼ੁਰੂਆਤੀ ਬਿੰਦੂ ਬਣ ਜਾਂਦੇ ਹਨ — ਤੁਸੀਂ ਹਾਲੇ ਵੀ ਵਿਜ਼ਾਰਡ ਵਿੱਚ ਹਰ ਕੈਂਪੇਨ ਲਈ ਇਹਨਾਂ ਨੂੰ ਬਦਲ ਸਕਦੇ ਹੋ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਹਰ ਕੈਂਪੇਨ ਲਈ ਆਪਣੇ ਆਪ ਲਾਗੂ ਹੁੰਦੀ ਹੈ। ਸ਼ਾਂਤ ਘੰਟੇ ਇੱਕ ਪਸੰਦ ਵਜੋਂ ਸੰਭਾਲੇ ਜਾਂਦੇ ਹਨ; ਭੇਜਣ ਵਾਲਾ ਇੰਜਣ ਹਾਲੇ ਇਸ ਉੱਤੇ ਕਾਰਵਾਈ ਨਹੀਂ ਕਰਦਾ।',
