  'set.openDefaultDesc': 'ਓਪਨ ਦਾ ਅਨੁਮਾਨ ਲਾਉਣ ਲਈ ਇੱਕ ਅਦਿੱਖ ਤਸਵੀਰ ਜੋੜਦਾ ਹੈ। ਤੁਸੀਂ ਹਾਲੇ ਵੀ ਇਸਨੂੰ ਹਰ ਕੈਂਪੇਨ ਲਈ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ।',
