  'set.clickDefaultDesc': 'ਲਿੰਕ ਦੁਬਾਰਾ ਲਿਖਦਾ ਹੈ ਤਾਂ ਜੋ ਕਲਿੱਕ ਗਿਣੇ ਜਾ ਸਕਣ। ਜੇ ਤੁਸੀਂ ਸਾਦੇ ਲਿੰਕ ਪਸੰਦ ਕਰਦੇ ਹੋ ਤਾਂ ਇਸਨੂੰ ਬੰਦ ਕਰੋ।',
