  'set.locationDesc': 'IP ਪਤਾ ਪਹਿਲਾਂ ਹੀ ਹਮੇਸ਼ਾ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ — ਇਹ ਸਵਿੱਚ ਹਾਲੇ ਦੇਸ਼ ਦਾ ਨਾਮ ਚਾਲੂ ਜਾਂ ਬੰਦ ਨਹੀਂ ਕਰਦਾ, ਕਿਉਂਕਿ ਹਾਲੇ ਕੋਈ ਲੁੱਕਅੱਪ ਕਦਮ ਮੌਜੂਦ ਨਹੀਂ।',
  'set.openEstimateNote': 'ਓਪਨ ਦੀ ਗਿਣਤੀ ਹਮੇਸ਼ਾ ਇੱਕ ਅਨੁਮਾਨ ਹੈ। ਤਸਵੀਰ ਰੋਕਣਾ ਅਸਲੀ ਓਪਨ ਲੁਕਾਉਂਦਾ ਹੈ, ਅਤੇ ਪ੍ਰਾਈਵੇਸੀ ਪ੍ਰੌਕਸੀ ਅਜਿਹੇ ਓਪਨ ਬਣਾਉਂਦੇ ਹਨ ਜੋ ਕਦੇ ਹੋਏ ਹੀ ਨਹੀਂ। ਇਸੇ ਕਾਰਨ ਅਸੀਂ ਹਰ ਓਪਨ ਨੂੰ "Open detected" ਵਜੋਂ ਲੇਬਲ ਕਰਦੇ ਹਾਂ।',
  'set.trackingNote': 'ਓਪਨ ਅਤੇ ਕਲਿੱਕ ਟਰੈਕਿੰਗ ਡਿਫ਼ਾਲਟ ਅਸਲ ਵਿੱਚ ਹਰ ਨਵੇਂ ਕੈਂਪੇਨ ਉੱਤੇ ਲਾਗੂ ਹੁੰਦੇ ਹਨ (ਤੁਸੀਂ ਹਾਲੇ ਵੀ ਹਰ ਕੈਂਪੇਨ ਲਈ ਬਦਲ ਸਕਦੇ ਹੋ)। ਡਿਵਾਈਸ ਅਤੇ ਟਿਕਾਣਾ ਹੁਣ ਲਈ ਸਿਰਫ਼ ਇੱਕ ਪਸੰਦ ਵਜੋਂ ਸੰਭਾਲੇ ਜਾਂਦੇ ਹਨ — ਕੱਚਾ user-agent ਅਤੇ IP ਇਹਨਾਂ ਦੋ ਸਵਿੱਚਾਂ ਦੀ ਪਰਵਾਹ ਕੀਤੇ ਬਿਨਾਂ ਹਰ ਓਪਨ ਉੱਤੇ ਦਰਜ ਹੁੰਦੇ ਹਨ।',
