  'set.templateOptionsNote': 'ਕਿਸੇ ਤਰੀਕੇ ਨੂੰ ਬੰਦ ਕਰਨ ਨਾਲ ਇਹ ਸਿਰਫ਼ ਲੁਕ ਜਾਂਦਾ ਹੈ — ਨਵੇਂ ਟੈਂਪਲੇਟ, ਅਤੇ ਹਰ ਥਾਂ ਇਹ ਸੂਚੀਬੱਧ ਹੁੰਦਾ ਹੈ — ਕੁਝ ਵੀ ਕਦੇ ਮਿਟਾਇਆ ਨਹੀਂ ਜਾਂਦਾ। ਉਸ ਕਿਸਮ ਦੇ ਮੌਜੂਦਾ ਟੈਂਪਲੇਟ ਸੁਰੱਖਿਅਤ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਦੁਬਾਰਾ ਚਾਲੂ ਕਰਨ ਦੇ ਤੁਰੰਤ ਬਾਅਦ ਵਾਪਸ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ।',
