  'seg.resendDesc': 'ਜਿਨ੍ਹਾਂ ਦਾ ਕੋਈ ਦਰਜ ਓਪਨ ਨਹੀਂ ਹੈ ਉਹਨਾਂ ਸਭ ਲਈ ਇੱਕ ਨਵਾਂ ਕੈਂਪੇਨ ਬਣਾਉਂਦਾ ਹੈ। ਅਸੀਂ ਤੁਹਾਨੂੰ ਬਿਲਕੁਲ ਸਹੀ ਗਿਣਤੀ ਦਿਖਾਉਂਦੇ ਹਾਂ ਅਤੇ ਕੁਝ ਵੀ ਬਣਨ ਤੋਂ ਪਹਿਲਾਂ ਪੁਸ਼ਟੀ ਮੰਗਦੇ ਹਾਂ।',
